<?php

/* @autogenerated */
declare(strict_types=1);

namespace {
    use PHPUnit\Framework\TestCase;
    use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
    use Slim\Routing\RouteCollectorProxy;
    use Slim\Interfaces\RouteGroupInterface;
    use Civi\Lughauth\Bootstrap\Plugin\OAuthPlugin;
    use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
    use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
    use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ApiKeyStoreGateway;
    use Civi\Lughauth\Features\OAuth\User\Domain\Gateway\LoginGateway;
    use Civi\Lughauth\Features\OAuth\TokenSecurity\Domain\Gateway\TokenSigner;
    use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
    use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkGateway;

    /**
     * Unit tests for {@see OAuthPlugin}.
     */
    #[AllowMockObjectsWithoutExpectations]
    final class OAuthPluginUnitTest extends TestCase
    {
        /**
         * Ensures OAuthPlugin is a MicroPlugin.
         */
        public function testIsMicroPlugin(): void
        {
            $plugin = new OAuthPlugin();

            $this->assertInstanceOf(MicroPlugin::class, $plugin);
        }

        /**
         * Ensures registerServiceDefinition binds all expected gateway interfaces.
         */
        public function testRegisterServiceDefinitionBindsGateways(): void
        {
            $plugin = new OAuthPlugin();

            $result = $plugin->registerServiceDefinition([]);

            $this->assertArrayHasKey(ClientStoreGateway::class, $result);
            $this->assertArrayHasKey(ApiKeyStoreGateway::class, $result);
            $this->assertArrayHasKey(LoginGateway::class, $result);
            $this->assertArrayHasKey(TokenSigner::class, $result);
            $this->assertArrayHasKey(SessionStoreGateway::class, $result);
            $this->assertArrayHasKey(MagicLinkGateway::class, $result);
        }

        /**
         * Ensures registerServiceDefinition preserves existing definitions.
         */
        public function testRegisterServiceDefinitionPreservesExistingDefs(): void
        {
            $plugin = new OAuthPlugin();

            $result = $plugin->registerServiceDefinition(['existing' => 'value']);

            $this->assertArrayHasKey('existing', $result);
            $this->assertSame('value', $result['existing']);
        }

        /**
         * Ensures registerRoutes registers top-level and grouped routes without errors.
         */
        public function testRegisterRoutesRegistersExpectedRoutes(): void
        {
            $plugin = new OAuthPlugin();

            $innerCollector = $this->getMockBuilder(RouteCollectorProxy::class)
                ->disableOriginalConstructor()
                ->getMock();
            $routeGroup = $this->createMock(RouteGroupInterface::class);

            $collector = $this->getMockBuilder(RouteCollectorProxy::class)
                ->disableOriginalConstructor()
                ->getMock();

            $collector->method('group')
                ->willReturnCallback(
                    function (string $pattern, callable $callable) use ($innerCollector, $routeGroup): RouteGroupInterface {
                        $callable($innerCollector);
                        return $routeGroup;
                    }
                );

            $collector->expects($this->atLeastOnce())->method('get');

            $plugin->registerRoutes($collector);
        }
    }
}
